const agentsNum = 900;
const zoom = 500;
const agent = (d) => ({
  degree: d,
  radius: 1 + random(0.05),
  x: 0,
  y: random(-1, 1),
  z: 0,
});

const system = {
  agents: [],
  lines: [],
  init() {
    for (let i = agentsNum; i--; ) {
      this.agents.push(agent(i / 175));
    }
  },
  update() {
    for (const a of this.agents) {
      const d = a.degree + frameCount / 100;
      a.x = cos(d);
      a.z = a.radius * (sin(d) + 2);
    }
  },
  relativeNeighborhoodGraph() {
    for (let i = this.agents.length; i--; ) {
      const current = this.agents[i];
      for (let j = i; j--; ) {
        const other = this.agents[j];
        const d = this.distance(other, current);
        if (
          this.agents.every(
            (any) =>
              d <= this.distance(current, any) || d <= this.distance(other, any)
          )
        ) {
          this.lines.push([current, other]);
        }
      }
    }
  },
  distance(a, b) {
    return (a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2;
  },

  render() {
    translate(width / 2, height / 2);
    fill("white");
    stroke("black");

    for (const [a, b] of this.lines) {
      const ax = a.x / a.z;
      const ay = a.y / a.z;
      const bx = b.x / b.z;
      const by = b.y / b.z;
      strokeWeight(10 / (a.z * b.z));
      line(ax * zoom * 1.5, ay * zoom, bx * zoom * 1.5, by * zoom);
    }
  },
};

setup = () => {
  createCanvas(windowWidth, windowHeight);
  system.init();
  system.update();
  system.relativeNeighborhoodGraph();
  rectMode(CENTER);
};

draw = (_) => {
  background("white");
  system.update();
  system.render();
};
